import { ScoredCountry } from '@/scoring/types';

// 2025 Global Peace Index Data (Source: Institute for Economics & Peace)
// GPI scores range from ~1.0 (most peaceful) to ~3.5 (least peaceful)
// Converted to 1-10 safety scale where higher = safer
const createScore = (gpiScore: number) => {
  const minGPI = 1.0;
  const maxGPI = 3.5;
  const safety = Math.round((1 - (gpiScore - minGPI) / (maxGPI - minGPI)) * 100) / 10;
  return Math.max(1, Math.min(10, safety));
};

// Pillar estimation based on GPI sub-indicators (deterministic)
const estimatePillars = (rank: number, gpiScore: number) => {
  const base = Math.max(0.3, 1 - (gpiScore - 1) / 2.5);
  const conflict = rank < 50 ? base + 0.2 : rank < 100 ? base : base - 0.1;
  const crime = rank < 30 ? base + 0.15 : rank < 80 ? base + 0.05 : base - 0.05;
  const health = rank < 40 ? 0.9 : rank < 100 ? 0.8 : 0.6;
  const governance = rank < 50 ? base + 0.2 : base;
  const environment = 0.75 + (base * 0.1);
  
  return [
    { name: 'conflict' as const, displayName: 'Conflict', value: Math.min(1, conflict), weight: 0.30 },
    { name: 'crime' as const, displayName: 'Crime', value: Math.min(1, crime), weight: 0.25 },
    { name: 'health' as const, displayName: 'Health', value: Math.min(1, health), weight: 0.20 },
    { name: 'governance' as const, displayName: 'Governance', value: Math.min(1, governance), weight: 0.15 },
    { name: 'environment' as const, displayName: 'Environment', value: Math.min(1, environment), weight: 0.10 },
  ];
};

